import fs from "node:fs";
const src = fs.readFileSync(process.argv[2], "utf8");
const head = src.slice(0, src.indexOf("\n", src.indexOf("const ALL_MODES")));
const api = src.slice(src.indexOf("// ---------- Talking to the backend"), src.indexOf("// ---------- Trusted contacts"));
const store = {};
globalThis.localStorage = { getItem: (k) => store[k] ?? null, setItem: (k, v) => { store[k] = String(v); } };
globalThis.location = { protocol: "http:" };
globalThis.window = { crypto: globalThis.crypto };
let dbDown = false;
const realFetch = fetch;
globalThis.fetch = (url, opts) => dbDown
  ? Promise.resolve(new Response('{"error":"Server error"}', { status: 500 }))
  : realFetch("http://localhost:3999" + url, opts);
const MOCK_SCENARIOS = [];
const t = new Function("MOCK_SCENARIOS", head + api + `
return { apiSaveScore, apiLeaderboard, apiMasters, flushPending, checkBackend, isOffline: () => OFFLINE };`)(MOCK_SCENARIOS);
const show = (r) => r.rows.map((p) => `${p.username}:${p.total_score}[${p.badges}]`).join(" ");

